; t36_editpc - EDITPC with a few classic patterns and random ones (seed
; 1): every operator, leading zeros supplied and digits dropped by
; EO$ADJUST_INPUT, PSL<DV> (decimal overflow trap). Each case logs the PSL,
; R0-R5 and the destination. Generated by mk_t36.py; compared with the
; reference simulator.
;@ dump=18000:C00 clocks=8000000
	.include "mmsetup.inc"
test:
	movl	#S0+arith_h, @#^x34

; EDITPC 5 digits, pattern 95 00
