	movl	#^x11111111, r0
	movl	#^x22222222, r1
	movl	#^x33333333, r2
	movl	#^x44444444, r3
	movl	#^x55555555, r4
	movl	#^x66666666, r5
	bicpsw	#^xFF
	bispsw	#^xF
